      grid[nr][nc] = grid[r][c] + 1  // set distance
      queue.offer([nr, nc])           // mark visited`}),a.jsxs("div",{className:"mt-3 px-4 py-3 rounded-lg border text-xs leading-relaxed text-default-500",style:{background:`${Jt}0d`,borderColor:`${Jt}44`},children:[a.jsx("span",{style:{color:Jt},className:"font-bold",children:"⚠️ Key insight: "}),"No separate ",a.jsx("code",{children:"visited[][]"})," array needed! The act of writing a distance into a cell (replacing INF) ",a.jsx("em",{children:"is"})," the visited check. Walls (-1) are automatically skipped since -1 ≠ INF."]})]})}),a.jsx(A,{children:a.jsxs(_,{children:[a.jsx("p",{className:"text-xs font-bold text-default-500 uppercase tracking-wider mb-3",children:"Complexity"}),a.jsx("div",{className:"flex gap-3 flex-wrap",children:[{l:"TIME",v:"O(m · n)",s:"Every cell enqueued and dequeued at most once"},{l:"SPACE",v:"O(m · n)",s:"BFS queue can hold up to all cells in the grid"}].map(({l:x,v:E,s:N})=>a.jsxs("div",{className:"flex-1 rounded-lg p-4 text-center",style:{background:"var(--viz-surface)",border:"1px solid var(--viz-border)"},children:[a.jsx("p",{className:"text-xs text-default-500 mb-1",children:x}),a.jsx("p",{className:"font-bold text-base",style:{color:Nt},children:E}),a.jsx("p",{className:"text-xs text-default-400 mt-1",children:N})]},x))})]})})]})},"Intuition"),a.jsx(Y,{title:"Visualizer",children:a.jsxs("div",{className:"flex flex-col gap-4 max-w-3xl mx-auto py-4 pb-10",children:[a.jsx(A,{children:a.jsxs(_,{children:[a.jsx("p",{className:"text-xs font-bold text-default-500 uppercase tracking-wider mb-3",children:"Configure"}),a.jsx("div",{className:"flex gap-2 flex-wrap",children:ZM.map((x,E)=>a.jsx(ne,{size:"sm",variant:n===E?"flat":"bordered",color:n===E?"primary":"default",onPress:()=>r(E),children:x.label},x.label))}),a.jsx("div",{className:"flex gap-4 mt-4 flex-wrap text-xs text-default-500",children:[{color:Jt,symbol:"💎",label:"Treasure (0)"},{color:"rgba(80,80,90,0.8)",symbol:"▪",label:"Wall (-1)"},{color:"var(--viz-muted)",symbol:"∞",lab